from .errors import InvoiceError
from .tax import round_half_even
from datetime import date

class InvoiceService:
    def __init__(self, store):
        self.store = store

    def create(self, invoice):
        self.store.create(invoice)

    def get(self, invoice_id, user_id):
        invoice = self.store.get_invoice(invoice_id)
        if invoice is None:
            raise InvoiceError('NOT_FOUND')
        if invoice.owner != user_id:
            raise InvoiceError('FORBIDDEN')
        return invoice

    def total(self, invoice_id, user_id):
        invoice = self.store.get_invoice(invoice_id)
        if invoice is None:
            raise InvoiceError('NOT_FOUND')
        if invoice.owner != user_id:
            raise InvoiceError('FORBIDDEN')

        subtotal = sum(item.price * item.quantity for item in invoice.items)
        discount = sum(item.discount for item in invoice.items)
        discounted_amount = subtotal - discount

        gst_bp = 5  # Assuming 5% GST
        gst_amount = round_half_even(discounted_amount * gst_bp / 100)

        total_amount = discounted_amount + gst_amount

        return total_amount

